<script setup lang="ts">
/**
 * Login Page
 *
 * Login form connected to the backend JWT auth.
 * Generated by Blacksmith. You own this file — customize as needed.
 */
import { reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import type { FormSubmitEvent } from '@nuxt/ui'
import type { z } from 'zod'
import UButton from '@nuxt/ui/components/Button.vue'
import UForm from '@nuxt/ui/components/Form.vue'
import UFormField from '@nuxt/ui/components/FormField.vue'
import UInput from '@nuxt/ui/components/Input.vue'
import { Path } from '@/router/paths'
import TextLink from '@/shared/components/TextLink.vue'
import { useAuth } from '../composables/use-auth'
import { loginSchema } from '../schemas'
import AuthPanel from '../components/AuthPanel.vue'

const router = useRouter()
const route = useRoute()
const { login, error } = useAuth()

const state = reactive({ email: '', password: '' })
const submitting = ref(false)

async function onSubmit(event: FormSubmitEvent<z.output<typeof loginSchema>>) {
  submitting.value = true
  try {
    const result = await login(event.data.email, event.data.password)
    if (result.success) {
      const redirect = route.query.redirect
      await router.replace(typeof redirect === 'string' ? redirect : Path.Home)
    }
  } finally {
    submitting.value = false
  }
}
</script>

<template>
  <AuthPanel
    title="Welcome back"
    description="Enter your credentials to access your account."
    :error="error?.message"
  >
    <UForm
      :schema="loginSchema"
      :state="state"
      class="flex flex-col gap-4"
      @submit="onSubmit"
    >
      <UFormField label="Email address" name="email" required>
        <UInput
          v-model="state.email"
          type="email"
          autocomplete="email"
          placeholder="you@example.com"
          size="lg"
          class="w-full"
        />
      </UFormField>

      <UFormField label="Password" name="password" required>
        <UInput
          v-model="state.password"
          type="password"
          autocomplete="current-password"
          placeholder="Enter your password"
          size="lg"
          class="w-full"
        />
      </UFormField>

      <TextLink :to="Path.ForgotPassword" muted class="self-end text-sm">
        Forgot password?
      </TextLink>

      <UButton
        type="submit"
        size="lg"
        block
        :loading="submitting"
        class="mt-2"
      >
        Continue
      </UButton>
    </UForm>

    <template #footer>
      <p>
        Don't have an account?
        <TextLink :to="Path.Register">
          Sign up
        </TextLink>
      </p>
    </template>
  </AuthPanel>
</template>
